def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = frozenset((r, c) for r in range(h) for c in range(w) if grid[r][c] == 8)

    shapes = {
        1: [(0, 0), (0, 1), (1, 0), (1, 1)],
        2: [(0, 1), (1, 0), (1, 1)],
        3: [(0, 0), (0, 1), (1, 1)],
        4: [(0, 0), (1, 0), (1, 1)],
    }

    placements = {}
    for color, shape in shapes.items():
        for r in range(h - 1):
            for c in range(w - 1):
                tile = frozenset((r + dr, c + dc) for dr, dc in shape)
                placements.setdefault(color, []).append(tile)

    containing = {p: [] for p in cells}
    for color in sorted(placements):
        for tile in placements[color]:
            if tile <= cells:
                for p in tile:
                    containing[p].append((color, tile))

    memo = {}

    def solve(remaining):
        if not remaining:
            return {}
        if remaining in memo:
            return None

        p = min(remaining)
        for color, tile in containing[p]:
            if tile <= remaining:
                rest = solve(remaining - tile)
                if rest is not None:
                    result = dict(rest)
                    for q in tile:
                        result[q] = color
                    return result

        memo[remaining] = None
        return None

    colored = solve(cells)
    if colored is None:
        return [row[:] for row in grid]

    out = [[0] * w for _ in range(h)]
    for (r, c), color in colored.items():
        out[r][c] = color
    return out
